package com.maramigo.marketplace;
import com.maramigo.support.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.test.context.*;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

/** Two independent stores, real HTTP sessions, PostgreSQL and mixed fulfilment. @author Maram Abbas */
@ActiveProfiles("demo")
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"server.servlet.session.cookie.secure=false","maramigo.login-limit=300","DEMO_ADMIN_EMAIL=owner@example.test","DEMO_ADMIN_PASSWORD=Owner-test-password-2026"})
class PortfolioIT {
 static final TestPostgres db=new TestPostgres();
 @DynamicPropertySource static void configure(DynamicPropertyRegistry p)throws Exception{db.configure(p);}
 @AfterAll static void cleanup()throws Exception{db.close();}
 @org.springframework.test.context.bean.override.mockito.MockitoBean com.maramigo.accounts.AccountMail mail;
 final java.util.Map<String,String> delivered=new java.util.concurrent.ConcurrentHashMap<>();
 @BeforeEach void mailbox(){org.mockito.Mockito.when(mail.mode()).thenReturn("file");org.mockito.Mockito.doAnswer(call->{delivered.put(call.getArgument(0)+":"+call.getArgument(1),call.getArgument(2));return null;}).when(mail).send(org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyString());}
 @Autowired com.maramigo.accounts.AccountRequestQueue queue;
 @LocalServerPort int port;@Autowired ObjectMapper json;@Autowired JdbcTemplate jdbc;
 static final String PASSWORD="Market-test-password-2026";
 SessionClient owner()throws Exception{var c=new SessionClient(port,json);c.login("owner@example.test","Owner-test-password-2026");return c;}
 Map<String,Object> form(String email){return Map.of("ownerName","Synthetic Merchant","businessName","Synthetic shop "+UUID.randomUUID(),"businessType","Makeup","registrationNumber","DEMO-ONLY","phone","0500000000","email",email,"description","Synthetic integration store","password",PASSWORD,"confirmPassword",PASSWORD,"termsAccepted",true);}
 record Merchant(SessionClient client,long company,String email){}
 Merchant merchant(boolean approve)throws Exception{String email="merchant-"+UUID.randomUUID()+"@example.test";var c=new SessionClient(port,json);var registered=c.send("POST","/api/auth/business-register",form(email),true);assertThat(registered.statusCode()).as(registered.body()).isEqualTo(201);c.login(email,PASSWORD);long id=json.readTree(c.get("/api/merchant/store").body()).get("companyId").asLong();if(approve)assertThat(owner().send("PATCH","/api/admin/stores/"+id,Map.of("status","APPROVED","reason","Synthetic approval"),true).statusCode()).isEqualTo(200);return new Merchant(c,id,email);}
 SessionClient customer()throws Exception{var c=new SessionClient(port,json);String email="buyer-"+UUID.randomUUID()+"@example.test";assertThat(c.send("POST","/api/auth/register",Map.of("email",email,"password",PASSWORD),true).statusCode()).isEqualTo(201);c.login(email,PASSWORD);return c;}
 Map<String,Object> productData(long company){return Map.of("sku","MR-"+UUID.randomUUID().toString().toUpperCase(Locale.ROOT),"name","Synthetic marketplace item","description","Test product","category","Makeup","price","10.00","active",true,"companyId",company);}
 JsonNode product(Merchant m,long forgedCompany)throws Exception{var r=m.client().send("POST","/api/merchant/products",Map.of("product",productData(forgedCompany),"initialStock",5),true);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json.readTree(r.body());}
 String checkout(SessionClient c,JsonNode... products)throws Exception{var lines=Arrays.stream(products).map(p->Map.of("productId",p.get("id").asLong(),"quantity",1,"expectedPrice","10.00")).toList();var shipping=Map.of("fullName","Synthetic Buyer","phone","0500000000","address","1 Test St","city","Test","postalCode","0000000","country","IL");var r=c.send("POST","/api/orders",Map.of("shipping",shipping,"items",lines),true,UUID.randomUUID().toString());assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json.readTree(r.body()).get("orderNumber").asText();}

 String paid(SessionClient c,String outcome,JsonNode... ps)throws Exception{var lines=Arrays.stream(ps).map(p->Map.of("productId",p.get("id").asLong(),"quantity",1,"expectedPrice","10.00")).toList();var r=c.send("POST","/api/orders",Map.of("items",lines,"shipping",Map.of("fullName","Synthetic Buyer","phone","0500000000","address","1 Test St","city","Test","postalCode","0000000","country","IL"),"demoPaymentOutcome",outcome),true,UUID.randomUUID().toString());assertThat(r.statusCode()).as(r.body()).isEqualTo(outcome.equals("DECLINED")?402:200);return outcome.equals("DECLINED")?"":json.readTree(r.body()).get("orderNumber").asText();}
 long orderId(String number){return jdbc.queryForObject("SELECT id FROM orders WHERE order_number=?",Long.class,number);}
 int stock(JsonNode p){return jdbc.queryForObject("SELECT stock_quantity FROM products WHERE id=?",Integer.class,p.get("id").asLong());}
 @Test void declinedSimulationCreatesNeitherOrderNorStockMovement()throws Exception{var m=merchant(true);var p=product(m,1);var c=customer();long count=jdbc.queryForObject("SELECT count(*) FROM orders",Long.class);paid(c,"DECLINED",p);assertThat(stock(p)).isEqualTo(5);assertThat(jdbc.queryForObject("SELECT count(*) FROM orders",Long.class)).isEqualTo(count);}
 @Test void captureIsIdempotentAndCommissionUsesStoreSnapshots()throws Exception{var a=merchant(true);var b=merchant(true);var pa=product(a,1);var pb=product(b,1);var c=customer();String number=paid(c,"SUCCESS",pa,pb);long id=orderId(number);assertThat(stock(pa)).isEqualTo(4);assertThat(c.send("POST","/api/customer/payments/"+number,Map.of(),true).statusCode()).isEqualTo(200);assertThat(jdbc.queryForObject("SELECT amount_agorot FROM demo_payments WHERE order_id=?",Long.class,id)).isEqualTo(2000);assertThat(jdbc.queryForObject("SELECT sum(fee_agorot) FROM demo_ledger WHERE order_id=?",Long.class,id)).isEqualTo(100);assertThat(jdbc.queryForObject("SELECT count(*) FROM demo_ledger WHERE order_id=?",Long.class,id)).isEqualTo(2);assertThat(a.client().get("/api/merchant/finance").body()).doesNotContain(pb.get("sku").asText());assertThat(customer().get("/api/customer/payments/"+number).statusCode()).isEqualTo(404);}
 @Test void mixedCancellationAndLaterPlatformCancellationRestoreEachPartOnce()throws Exception{var a=merchant(true);var b=merchant(true);var pa=product(a,1);var pb=product(b,1);var c=customer();String number=paid(c,"SUCCESS",pa,pb);var cancel=Map.of("companyId",a.company(),"kind","CANCEL","reason","Synthetic cancellation");for(int i=0;i<2;i++)assertThat(c.send("POST","/api/customer/returns/"+number,cancel,true).statusCode()).isEqualTo(200);assertThat(stock(pa)).isEqualTo(5);assertThat(stock(pb)).isEqualTo(4);var manager=owner();var detail=json.readTree(manager.get("/api/admin/orders/"+number).body());assertThat(manager.send("PATCH","/api/admin/orders/"+number+"/status",Map.of("status","CANCELLED","version",detail.get("version").asLong(),"reason","Synthetic remaining cancellation"),true).statusCode()).isEqualTo(200);assertThat(stock(pa)).isEqualTo(5);assertThat(stock(pb)).isEqualTo(5);assertThat(jdbc.queryForObject("SELECT refunded_agorot FROM demo_payments WHERE order_id=?",Long.class,orderId(number))).isEqualTo(2000);assertThat(jdbc.queryForObject("SELECT sum(gross_agorot) FROM demo_ledger WHERE order_id=?",Long.class,orderId(number))).isZero();assertThat(c.send("POST","/api/customer/stores/"+a.company()+"/messages",Map.of("body","Support after cancellation"),true).statusCode()).isEqualTo(200);}
 @Test void deliveredReturnIsTenantScopedAndDoubleApprovalDoesNotDoubleRefund()throws Exception{var a=merchant(true);var b=merchant(true);var p=product(a,1);var c=customer();String number=paid(c,"SUCCESS",p);for(int i=0;i<2;i++)assertThat(a.client().send("PATCH","/api/merchant/orders/"+number+"/status",Map.of("status",i==0?"SHIPPED":"DELIVERED","version",i,"reason","Synthetic delivery"),true).statusCode()).isEqualTo(200);assertThat(c.send("POST","/api/customer/returns/"+number,Map.of("companyId",a.company(),"kind","RETURN","reason","Synthetic return"),true).statusCode()).isEqualTo(200);long id=jdbc.queryForObject("SELECT id FROM return_requests WHERE order_id=?",Long.class,orderId(number));assertThat(b.client().send("POST","/api/merchant/returns/"+id,Map.of("status","COMPLETED","reason","Forbidden"),true).statusCode()).isEqualTo(404);for(int i=0;i<2;i++)assertThat(a.client().send("POST","/api/merchant/returns/"+id,Map.of("status","COMPLETED","reason","Received"),true).statusCode()).isEqualTo(200);assertThat(stock(p)).isEqualTo(5);assertThat(jdbc.queryForObject("SELECT status FROM demo_payments WHERE order_id=?",String.class,orderId(number))).isEqualTo("REFUNDED");}
 @Test void subscriptionsRequireConsentAndRepeatActivationDoesNotChargeTwice()throws Exception{var m=merchant(true);assertThat(m.client().send("POST","/api/merchant/subscription",Map.of("consent",false),true).statusCode()).isEqualTo(400);for(int i=0;i<2;i++)assertThat(m.client().send("POST","/api/merchant/subscription",Map.of("consent",true),true).statusCode()).isEqualTo(200);assertThat(jdbc.queryForObject("SELECT count(*) FROM demo_ledger WHERE company_id=? AND event='SUBSCRIPTION'",Long.class,m.company())).isEqualTo(1);assertThat(m.client().send("DELETE","/api/merchant/subscription",Map.of(),true).statusCode()).isEqualTo(200);assertThat(jdbc.queryForObject("SELECT status FROM demo_subscriptions WHERE company_id=?",String.class,m.company())).isEqualTo("CANCELLED");assertThat(m.client().send("POST","/api/merchant/subscription",Map.of("consent",true),true).statusCode()).isEqualTo(200);assertThat(jdbc.queryForObject("SELECT count(*) FROM demo_ledger WHERE company_id=? AND event='SUBSCRIPTION'",Long.class,m.company())).isEqualTo(1);var expired=merchant(true);jdbc.update("INSERT INTO demo_subscriptions(company_id,status,consent_at,period_start,period_end) VALUES (?,'ACTIVE',CURRENT_TIMESTAMP,CURRENT_DATE-60,CURRENT_DATE-1)",expired.company());assertThat(json.readTree(expired.client().get("/api/merchant/finance").body()).get("subscription").get(0).get("status").asText()).isEqualTo("EXPIRED");assertThat(expired.client().send("POST","/api/merchant/subscription",Map.of("consent",true),true).statusCode()).isEqualTo(200);assertThat(jdbc.queryForObject("SELECT count(*) FROM demo_ledger WHERE company_id=? AND event='SUBSCRIPTION'",Long.class,expired.company())).isEqualTo(1);}
 byte[] image()throws Exception{var image=new java.awt.image.BufferedImage(3,3,java.awt.image.BufferedImage.TYPE_INT_RGB);var out=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",out);return out.toByteArray();}
 @Test void uploadedImageIsReencodedPublishedAndScopedToItsOwner()throws Exception{var a=merchant(true);var b=merchant(true);var p=product(a,1);String path="/api/media/products/"+p.get("id").asLong();assertThat(b.client().upload(path,image(),true).statusCode()).isEqualTo(403);assertThat(a.client().upload(path,"<svg>invalid</svg>".getBytes(java.nio.charset.StandardCharsets.UTF_8),true).statusCode()).isEqualTo(400);var upload=a.client().upload(path,image(),true);assertThat(upload.statusCode()).as(upload.body()).isEqualTo(200);String id=json.readTree(upload.body()).get("id").asText();assertThat(new SessionClient(port,json).get("/api/media/"+id).statusCode()).isEqualTo(200);assertThat(json.readTree(a.client().get("/api/products/"+p.get("id").asLong()).body()).get("imageId").asText()).isEqualTo(id);assertThat(a.client().send("DELETE",path,Map.of(),true).statusCode()).isEqualTo(200);assertThat(new SessionClient(port,json).get("/api/media/"+id).statusCode()).isEqualTo(404);}
 @Test void passwordChangeNeedsCurrentPasswordAndRevokesExistingSession()throws Exception{var c=customer();String email=json.readTree(c.get("/api/auth/me").body()).get("email").asText();assertThat(c.send("POST","/api/account/password",Map.of("currentPassword","wrong","newPassword","Updated-password-2026"),true).statusCode()).isEqualTo(400);assertThat(c.send("POST","/api/account/password",Map.of("currentPassword",PASSWORD,"newPassword","Updated-password-2026"),true).statusCode()).isEqualTo(200);assertThat(c.get("/api/auth/me").statusCode()).isEqualTo(401);c.login(email,"Updated-password-2026");}
 @Test void emailChangeConfirmsNewAddressBeforeReplacingOldLogin()throws Exception{var c=customer();String old=json.readTree(c.get("/api/auth/me").body()).get("email").asText(),email="changed-"+UUID.randomUUID()+"@example.test";assertThat(c.send("POST","/api/account/email",Map.of("currentPassword",PASSWORD,"email",email),true).statusCode()).isEqualTo(200);assertThat(json.readTree(c.get("/api/auth/me").body()).get("email").asText()).isEqualTo(old);for(int i=0;i<200&&!delivered.containsKey(email+":EMAIL");i++)Thread.sleep(25);String token=delivered.get(email+":EMAIL");assertThat(token).isNotNull();for(int i=0;i<200&&jdbc.queryForObject("SELECT count(*) FROM account_tokens WHERE purpose='EMAIL'",Long.class)==0;i++)Thread.sleep(25);assertThat(new SessionClient(port,json).send("POST","/api/auth/confirm-email-change",Map.of("token",token),true).statusCode()).isEqualTo(204);assertThat(c.get("/api/auth/me").statusCode()).isEqualTo(401);c.login(email,PASSWORD);assertThat(jdbc.queryForObject("SELECT email_verified FROM users WHERE email=?",Boolean.class,email)).isTrue();}
 @Test void closureExportAndReviewAreScopedAndRejectOpenOrders()throws Exception{var m=merchant(true);var p=product(m,1);var c=customer();String email=json.readTree(c.get("/api/auth/me").body()).get("email").asText();String number=paid(c,"SUCCESS",p);assertThat(c.get("/api/account/export").body()).contains(number,email).doesNotContain("password_hash");assertThat(c.send("POST","/api/account/privacy",Map.of("currentPassword",PASSWORD,"reason","Synthetic closure"),true).statusCode()).isEqualTo(200);long request=jdbc.queryForObject("SELECT p.id FROM privacy_requests p JOIN users u ON u.id=p.user_id WHERE u.email=?",Long.class,email);assertThat(owner().send("POST","/api/admin/privacy/"+request,Map.of("status","COMPLETED","reason","Synthetic decision"),true).statusCode()).isEqualTo(409);assertThat(c.send("POST","/api/customer/returns/"+number,Map.of("companyId",m.company(),"kind","CANCEL","reason","Release order"),true).statusCode()).isEqualTo(200);assertThat(owner().send("POST","/api/admin/privacy/"+request,Map.of("status","COMPLETED","reason","Synthetic decision"),true).statusCode()).isEqualTo(200);assertThat(c.get("/api/auth/me").statusCode()).isEqualTo(401);assertThat(jdbc.queryForObject("SELECT shipping::text FROM orders WHERE order_number=?",String.class,number)).doesNotContain("Synthetic Buyer","1 Test St");}

 @Test void durableMailResumesAnAbandonedClaimAfterRestart()throws Exception{var c=customer();String email=json.readTree(c.get("/api/auth/me").body()).get("email").asText();UUID job=UUID.randomUUID();jdbc.update("INSERT INTO account_mail_jobs(id,email,purpose,status,attempts,claimed_at) VALUES (?,?,'VERIFY','RUNNING',1,CURRENT_TIMESTAMP-INTERVAL '2 minutes')",job,email);queue.recover();for(int i=0;i<200&&!"COMPLETED".equals(jdbc.queryForObject("SELECT status FROM account_mail_jobs WHERE id=?",String.class,job));i++)Thread.sleep(25);assertThat(jdbc.queryForObject("SELECT status FROM account_mail_jobs WHERE id=?",String.class,job)).isEqualTo("COMPLETED");assertThat(delivered.get(email+":VERIFY")).hasSize(43);}

 @Test void payoutRetryIsIdempotentAndRefundAfterPayoutShowsMerchantDebt()throws Exception{var m=merchant(true);var p=product(m,1);var c=customer();String number=paid(c,"SUCCESS",p);var manager=owner();var key=UUID.randomUUID();for(int i=0;i<2;i++)assertThat(manager.send("POST","/api/admin/payouts/"+m.company(),Map.of("requestKey",key),true).statusCode()).isEqualTo(200);assertThat(jdbc.queryForObject("SELECT count(*) FROM demo_payouts WHERE company_id=?",Long.class,m.company())).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT amount_agorot FROM demo_payouts WHERE company_id=?",Long.class,m.company())).isEqualTo(950);assertThat(c.send("POST","/api/customer/returns/"+number,Map.of("companyId",m.company(),"kind","CANCEL","reason","Synthetic post-payout refund"),true).statusCode()).isEqualTo(200);assertThat(manager.send("POST","/api/admin/payouts/"+m.company(),Map.of("requestKey",UUID.randomUUID()),true).statusCode()).isEqualTo(409);assertThat(json.readTree(m.client().get("/api/merchant/finance").body()).get("payoutAgorot").asLong()).isEqualTo(950);}

 @Test void olderUnpaidOrderCanPayOnlyItsRemainingActiveStorePart()throws Exception{var a=merchant(true);var b=merchant(true);var pa=product(a,1);var pb=product(b,1);var c=customer();String number=checkout(c,pa,pb);assertThat(c.send("POST","/api/customer/returns/"+number,Map.of("companyId",a.company(),"kind","CANCEL","reason","Cancel unpaid part"),true).statusCode()).isEqualTo(200);assertThat(c.send("POST","/api/customer/payments/"+number,Map.of(),true).statusCode()).isEqualTo(200);assertThat(jdbc.queryForObject("SELECT amount_agorot FROM demo_payments WHERE order_id=?",Long.class,orderId(number))).isEqualTo(1000);assertThat(jdbc.queryForObject("SELECT count(*) FROM demo_ledger WHERE order_id=?",Long.class,orderId(number))).isEqualTo(1);assertThat(stock(pa)).isEqualTo(5);assertThat(stock(pb)).isEqualTo(4);}

 @Test void checkoutRechecksStoreStateAfterWaitingForItsLock()throws Exception{var m=merchant(true);var p=product(m,1);var c=customer();var pool=java.util.concurrent.Executors.newSingleThreadExecutor();try(var connection=java.util.Objects.requireNonNull(jdbc.getDataSource()).getConnection()){connection.setAutoCommit(false);try(var lock=connection.prepareStatement("SELECT id FROM companies WHERE id=? FOR UPDATE")){lock.setLong(1,m.company());lock.executeQuery();}var future=pool.submit(()->c.send("POST","/api/orders",Map.of("items",List.of(Map.of("productId",p.get("id").asLong(),"quantity",1,"expectedPrice","10.00")),"shipping",Map.of("fullName","Synthetic Buyer","phone","0500000000","address","1 Test St","city","Test","postalCode","0000000","country","IL"),"demoPaymentOutcome","SUCCESS"),true,UUID.randomUUID().toString()).statusCode());boolean waiting=false;for(int i=0;i<120;i++){if(jdbc.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE wait_event_type='Lock' AND query LIKE 'SELECT status FROM companies WHERE id=%FOR UPDATE%'",Long.class)>0){waiting=true;break;}Thread.sleep(25);}assertThat(waiting).isTrue();try(var change=connection.prepareStatement("UPDATE companies SET status='SUSPENDED' WHERE id=?")){change.setLong(1,m.company());change.executeUpdate();}connection.commit();assertThat(future.get(20,java.util.concurrent.TimeUnit.SECONDS)).isEqualTo(409);assertThat(stock(p)).isEqualTo(5);}finally{pool.shutdownNow();}}
}
